import { readFileSync } from 'node:fs'

class Fail extends Error {}
const fail = (m) => { throw new Fail(m) }

const isBare = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)
const isWs = (c) => c === ' ' || c === '\t'
const mkTable = () => ({ t: 'table', m: new Map(), hdr: false })

function parseLine(line, root, st) {
  let i = 0
  const skip = () => { while (isWs(line[i])) i++ }
  const atEnd = () => i >= line.length || line[i] === '#' || line[i] === ';'

  function parseString(q) {
    i++
    let out = ''
    if (q === "'") {
      const j = line.indexOf("'", i)
      if (j < 0) fail('unterminated string')
      out = line.slice(i, j); i = j + 1
      return out
    }
    for (;;) {
      if (i >= line.length) fail('unterminated string')
      const c = line[i]
      if (c === '"') { i++; return out }
      if (c !== '\\') { out += c; i++; continue }
      i++
      if (i >= line.length) fail('unterminated string')
      const e = line[i]
      const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
      if (e in map) { out += map[e]; i++ } else if (e === 'u') {
        const h = line.slice(i + 1, i + 5)
        if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16)); i += 5
      } else fail('invalid escape \\' + String.fromCodePoint(line.codePointAt(i)))
    }
  }

  function parseName() {
    const c = line[i]
    if (c === '"' || c === "'") return parseString(c)
    const s = i
    while (isBare(line[i])) i++
    if (i === s) fail('expected a name')
    return line.slice(s, i)
  }

  function parseDotted() {
    const parts = [parseName()]
    for (;;) {
      const save = i
      skip()
      if (line[i] === '.') { i++; skip(); parts.push(parseName()) } else { i = save; break }
    }
    return parts
  }

  function parseValue(base) {
    skip()
    const c = line[i]
    if (c === '"' || c === "'") return { t: 'string', v: parseString(c) }
    if (c === '[') {
      i++
      const items = []
      for (;;) {
        skip()
        if (i >= line.length || atEnd()) fail('unterminated array')
        if (line[i] === ']') { i++; break }
        items.push(parseValue(base + '[' + items.length + ']'))
        skip()
        if (line[i] === ',') { i++; continue }
        if (line[i] === ']') { i++; break }
        fail('unterminated array')
      }
      return { t: 'array', items, aot: false }
    }
    if (c === '{') {
      i++
      const tbl = mkTable()
      skip()
      if (line[i] === '}') { i++; return tbl }
      for (;;) {
        skip()
        const parts = parseDotted()
        skip()
        if (line[i] !== '=') fail('expected = in an inline table')
        i++
        assign(tbl, parts, base, () => parseValue(base))
        skip()
        if (line[i] === ',') { i++; continue }
        if (line[i] === '}') { i++; break }
        fail('unterminated inline table')
      }
      return tbl
    }
    const s = i
    while (i < line.length && !isWs(line[i]) && !',]}'.includes(line[i])) i++
    const tok = line.slice(s, i)
    if (tok === '') fail('expected a value')
    if (tok === 'true' || tok === 'false') return { t: 'boolean', v: tok === 'true' }
    const D = '[0-9]+(?:_[0-9]+)*'
    if (new RegExp(`^[+-]?${D}$`).test(tok)) return { t: 'integer', v: Number(tok.replace(/_/g, '')) }
    if (new RegExp(`^[+-]?${D}(?:\\.${D}(?:[eE][+-]?${D})?|[eE][+-]?${D})$`).test(tok)) {
      return { t: 'float', v: Number(tok.replace(/_/g, '')) }
    }
    fail('invalid value ' + tok)
  }

  // walk intermediate names; returns the table holding the last name
  function walk(tbl, parts, base) {
    let cur = tbl
    let path = base
    for (let k = 0; k < parts.length - 1; k++) {
      path = path ? path + '.' + parts[k] : parts[k]
      let n = cur.m.get(parts[k])
      if (!n) { n = mkTable(); cur.m.set(parts[k], n) }
      if (n.t === 'table') cur = n
      else if (n.t === 'array' && n.aot) cur = n.items[n.items.length - 1]
      else fail(path + ' is not a table')
    }
    return { cur, path: parts.length > 1 ? path + '.' + parts[parts.length - 1] : (base ? base + '.' : '') + parts[0] }
  }

  function assign(tbl, parts, base, getVal) {
    const { cur, path } = walk(tbl, parts, base)
    const last = parts[parts.length - 1]
    if (cur.m.has(last)) fail(`key ${path} is defined twice`)
    cur.m.set(last, getVal())
  }

  skip()
  if (atEnd()) return
  if (line[i] === '[') {
    i++
    const arr = line[i] === '['
    if (arr) i++
    skip()
    const parts = parseDotted()
    skip()
    if (line[i] !== ']') fail('unterminated table header')
    i++
    if (arr) {
      if (line[i] !== ']') fail('unterminated table header')
      i++
    }
    skip()
    if (!atEnd()) fail('trailing text after a table header')
    const { cur, path } = walk(root, parts, '')
    const last = parts[parts.length - 1]
    const n = cur.m.get(last)
    if (arr) {
      const fresh = mkTable()
      if (!n) cur.m.set(last, { t: 'array', items: [fresh], aot: true })
      else if (n.t === 'array' && n.aot) n.items.push(fresh)
      else fail(path + ' is not an array of tables')
      st.cur = fresh
    } else {
      if (!n) {
        const t = mkTable(); t.hdr = true; cur.m.set(last, t); st.cur = t
      } else if (n.t !== 'table') fail(path + ' is not a table')
      else if (n.hdr) fail(`table ${path} is defined twice`)
      else { n.hdr = true; st.cur = n }
    }
    return
  }
  const parts = parseDotted()
  skip()
  if (line[i] !== '=') fail('expected key = value')
  i++
  const base = st.path
  assign(st.cur, parts, '', () => {
    const v = parseValue('')
    skip()
    if (!atEnd()) fail('trailing text after a value')
    return v
  })
}

function cmp(a, b) {
  const x = Array.from(a, (c) => c.codePointAt(0)), y = Array.from(b, (c) => c.codePointAt(0))
  for (let k = 0; k < Math.min(x.length, y.length); k++) if (x[k] !== y[k]) return x[k] - y[k]
  return x.length - y.length
}
const sortedKeys = (m) => [...m.keys()].sort(cmp)

function toJson(n, ind) {
  const pad = '  '.repeat(ind + 1), end = '  '.repeat(ind)
  if (n.t === 'table') {
    if (!n.m.size) return '{}'
    return '{\n' + sortedKeys(n.m).map((k) => pad + JSON.stringify(k) + ': ' + toJson(n.m.get(k), ind + 1)).join(',\n') + '\n' + end + '}'
  }
  if (n.t === 'array') {
    if (!n.items.length) return '[]'
    return '[\n' + n.items.map((x) => pad + toJson(x, ind + 1)).join(',\n') + '\n' + end + ']'
  }
  return JSON.stringify(n.v)
}

function keys(n, path, out) {
  if (n.t === 'table') {
    for (const k of sortedKeys(n.m)) {
      const p = path ? path + '.' + k : k
      const c = n.m.get(k)
      out.push(p + ' ' + c.t); keys(c, p, out)
    }
  } else if (n.t === 'array') {
    n.items.forEach((c, k) => { const p = path + '[' + k + ']'; out.push(p + ' ' + c.t); keys(c, p, out) })
  }
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'json' && args[0] !== 'keys')) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}
const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()
const root = mkTable()
const st = { cur: root, path: '' }
try {
  lines.forEach((l, k) => {
    try { parseLine(l, root, st) } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${k + 1}: ${e.message}`)
      throw e
    }
  })
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write('error: ' + e.message + '\n')
  process.exit(2)
}
if (args[0] === 'json') process.stdout.write(toJson(root, 0) + '\n')
else { const out = []; keys(root, '', out); process.stdout.write(out.map((l) => l + '\n').join('')) }
